class Solution {
  public long minCost(int m, int n, int[][] waitCost) {
    long INF = Long.MAX_VALUE / 4;
    long[][] dp = new long[m][n];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (i == 0 && j == 0) {
          dp[0][0] = 1;
          continue;
        }
        long best = INF;
        if (i > 0)
          best = Math.min(best, dp[i - 1][j] + (i - 1 == 0 && j == 0 ? 0 : waitCost[i - 1][j]));
        if (j > 0)
          best = Math.min(best, dp[i][j - 1] + (i == 0 && j - 1 == 0 ? 0 : waitCost[i][j - 1]));
        dp[i][j] = best + (long) (i + 1) * (j + 1);
      }
    }
    return dp[m - 1][n - 1];
  }
}
